-- Normalized 14-table reference schema.
CREATE TABLE IF NOT EXISTS students(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,phone VARCHAR(30));
CREATE TABLE IF NOT EXISTS departments(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS programs(id BIGSERIAL PRIMARY KEY,department_id BIGINT REFERENCES departments(id),name VARCHAR(120) NOT NULL);
CREATE TABLE IF NOT EXISTS courses(id BIGSERIAL PRIMARY KEY,code VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(160) NOT NULL);
CREATE TABLE IF NOT EXISTS semesters(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL,start_date DATE,end_date DATE);
CREATE TABLE IF NOT EXISTS instructors(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE);
CREATE TABLE IF NOT EXISTS classrooms(id BIGSERIAL PRIMARY KEY,building VARCHAR(80),room_no VARCHAR(30));
CREATE TABLE IF NOT EXISTS course_offerings(id BIGSERIAL PRIMARY KEY,course_id BIGINT REFERENCES courses(id),semester_id BIGINT REFERENCES semesters(id),instructor_id BIGINT REFERENCES instructors(id),classroom_id BIGINT REFERENCES classrooms(id));
CREATE TABLE IF NOT EXISTS enrollments(id BIGSERIAL PRIMARY KEY,student_id BIGINT REFERENCES students(id),course_id BIGINT REFERENCES courses(id),enrolled_on DATE NOT NULL,status VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS fee_types(id BIGSERIAL PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS fee_invoices(id BIGSERIAL PRIMARY KEY,student_id BIGINT REFERENCES students(id),fee_type_id BIGINT REFERENCES fee_types(id),amount NUMERIC(12,2) NOT NULL,due_date DATE);
CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,invoice_id BIGINT REFERENCES fee_invoices(id),amount NUMERIC(12,2) NOT NULL,paid_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,username VARCHAR(100) UNIQUE NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roles(id BIGSERIAL PRIMARY KEY,name VARCHAR(50) UNIQUE NOT NULL);
